    if (tb_gfresh == tb_gfresh_end) { tb_gfresh = tb_gsys(64 * TB_GPG); tb_gfresh_end = tb_gfresh + 64 * TB_GPG; }
    char *p = tb_gfresh;
    tb_gfresh += TB_GPG;
    return p;
