    { const char * tb_v1066 = "#ifndef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v1066; }
    { const char * tb_v1067 = "// ---------- падение по памяти: понятное сообщение вместо «Segmentation fault» ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v1067; }
    { const char * tb_v1068 = "// Чаще всего это стек: функция зовёт себя слишком глубоко. Обработчик работает\n"; *(const char * *)tb_grow(v_lines) = tb_v1068; }
    { const char * tb_v1069 = "// на своём маленьком стеке (sigaltstack), потому что основной уже кончился.\n"; *(const char * *)tb_grow(v_lines) = tb_v1069; }
    { const char * tb_v1070 = "#ifndef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v1070; }
    { const char * tb_v1071 = "#include <signal.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v1071; }
    { const char * tb_v1072 = "#include <sys/resource.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v1072; }
    { const char * tb_v1073 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v1073; }
    { const char * tb_v1074 = "// На Windows нет сигналов и sigaltstack: переполнение стека ловит обработчик\n"; *(const char * *)tb_grow(v_lines) = tb_v1074; }
    { const char * tb_v1075 = "// исключений (tb_guard_init ниже), а место для него в конце стека даёт\n"; *(const char * *)tb_grow(v_lines) = tb_v1075; }
    { const char * tb_v1076 = "// SetThreadStackGuarantee. Этот sigaltstack только помнит память потока,\n"; *(const char * *)tb_grow(v_lines) = tb_v1076; }
    { const char * tb_v1077 = "// чтобы tb_tramp_run мог её отдать, и просит у Windows запас стека.\n"; *(const char * *)tb_grow(v_lines) = tb_v1077; }
    { const char * tb_v1078 = "typedef struct { void *ss_sp; size_t ss_size; int ss_flags; } stack_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v1078; }
    { const char * tb_v1079 = "#define SS_DISABLE 4\n"; *(const char * *)tb_grow(v_lines) = tb_v1079; }
    { const char * tb_v1080 = "static _Thread_local void *tb_win_alt;\n"; *(const char * *)tb_grow(v_lines) = tb_v1080; }
    { const char * tb_v1081 = "static int sigaltstack(const stack_t *ss, stack_t *old) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1081; }
    { const char * tb_v1082 = "    if (old) { old->ss_sp = tb_win_alt; old->ss_size = 0; old->ss_flags = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v1082; }
    { const char * tb_v1083 = "    if (ss) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1083; }
    { const char * tb_v1084 = "        tb_win_alt = (ss->ss_flags & SS_DISABLE) ? 0 : ss->ss_sp;\n"; *(const char * *)tb_grow(v_lines) = tb_v1084; }
    { const char * tb_v1085 = "        if (!(ss->ss_flags & SS_DISABLE)) { ULONG g = 65536; SetThreadStackGuarantee(&g); }\n"; *(const char * *)tb_grow(v_lines) = tb_v1085; }
    { const char * tb_v1086 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v1086; }
    { const char * tb_v1087 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1087; }
    { const char * tb_v1088 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1088; }
    { const char * tb_v1089 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v1089; }
    { const char * tb_v1090 = "// у каждого потока своё: где начинается его стек и сколько в нём места\n"; *(const char * *)tb_grow(v_lines) = tb_v1090; }
    { const char * tb_v1091 = "static _Thread_local char *tb_main_sp;\n"; *(const char * *)tb_grow(v_lines) = tb_v1091; }
    { const char * tb_v1092 = "static _Thread_local long long tb_stack_lim;\n"; *(const char * *)tb_grow(v_lines) = tb_v1092; }
    { const char * tb_v1093 = "#define TB_THREAD_STACK (8LL << 20)\n"; *(const char * *)tb_grow(v_lines) = tb_v1093; }
    { const char * tb_v1094 = "#ifndef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v1094; }
    { const char * tb_v1095 = "static void tb_on_segv(int sig, siginfo_t *si, void *u) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1095; }
    { const char * tb_v1096 = "    (void)sig; (void)u;\n"; *(const char * *)tb_grow(v_lines) = tb_v1096; }
