    { const char * tb_v1098 = "    long long lim = tb_stack_lim;\n"; *(const char * *)tb_grow(v_lines) = tb_v1098; }
    { const char * tb_v1099 = "    if (lim == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1099; }
    { const char * tb_v1100 = "        lim = 8LL << 20;\n"; *(const char * *)tb_grow(v_lines) = tb_v1100; }
    { const char * tb_v1101 = "        struct rlimit rl;\n"; *(const char * *)tb_grow(v_lines) = tb_v1101; }
    { const char * tb_v1102 = "        if (getrlimit(RLIMIT_STACK, &rl) == 0 && rl.rlim_cur != RLIM_INFINITY) lim = (long long)rl.rlim_cur;\n"; *(const char * *)tb_grow(v_lines) = tb_v1102; }
    { const char * tb_v1103 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v1103; }
    { const char * tb_v1104 = "    const char *m;\n"; *(const char * *)tb_grow(v_lines) = tb_v1104; }
    { const char * tb_v1105 = "    if (tb_main_sp && a <= tb_main_sp + 65536 && a >= tb_main_sp - lim - (1 << 20))\n"; *(const char * *)tb_grow(v_lines) = tb_v1105; }
    { const char * tb_v1106 = "        m = \"стек переполнен: функция зовёт себя слишком глубоко (рекурсия без конца?)\\n\";\n"; *(const char * *)tb_grow(v_lines) = tb_v1106; }
    { const char * tb_v1107 = "    else\n"; *(const char * *)tb_grow(v_lines) = tb_v1107; }
    { const char * tb_v1108 = "        m = \"программа упала: ошибка памяти. Это ошибка Tachbit, а не твоя: пришли, пожалуйста, эту программу\\n\";\n"; *(const char * *)tb_grow(v_lines) = tb_v1108; }
    { const char * tb_v1109 = "    if (write(2, m, strlen(m)) < 0) _exit(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v1109; }
    { const char * tb_v1110 = "    _exit(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v1110; }
    { const char * tb_v1111 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1111; }
    { const char * tb_v1112 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v1112; }
    { const char * tb_v1113 = "// свой маленький стек для сообщения: у главного потока — постоянный, у остальных — из malloc\n"; *(const char * *)tb_grow(v_lines) = tb_v1113; }
    { const char * tb_v1114 = "static void tb_guard_thread(char *here, long long lim) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1114; }
    { const char * tb_v1115 = "    stack_t ss;\n"; *(const char * *)tb_grow(v_lines) = tb_v1115; }
    { const char * tb_v1116 = "    ss.ss_sp = malloc(65536); ss.ss_size = 65536; ss.ss_flags = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1116; }
    { const char * tb_v1117 = "    if (ss.ss_sp) sigaltstack(&ss, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v1117; }
    { const char * tb_v1118 = "    tb_main_sp = here;\n"; *(const char * *)tb_grow(v_lines) = tb_v1118; }
    { const char * tb_v1119 = "    tb_stack_lim = lim;\n"; *(const char * *)tb_grow(v_lines) = tb_v1119; }
    { const char * tb_v1120 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1120; }
    { const char * tb_v1121 = "// поток background или ядра: сначала ставим защиту стека, потом сама работа\n"; *(const char * *)tb_grow(v_lines) = tb_v1121; }
    { const char * tb_v1122 = "// сколько потоков background / ядер работает сейчас: уборка памяти ждёт, пока их нет\n"; *(const char * *)tb_grow(v_lines) = tb_v1122; }
    { const char * tb_v1123 = "static int tb_gthreads = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1123; }
    { const char * tb_v1124 = "typedef struct { void *(*run)(void *); void *arg; } tb_tramp;\n"; *(const char * *)tb_grow(v_lines) = tb_v1124; }
    { const char * tb_v1125 = "static void *tb_tramp_run(void *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1125; }
    { const char * tb_v1126 = "    tb_tramp t = *(tb_tramp *)p;\n"; *(const char * *)tb_grow(v_lines) = tb_v1126; }
    { const char * tb_v1127 = "    free(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v1127; }
    { const char * tb_v1128 = "    char here;\n"; *(const char * *)tb_grow(v_lines) = tb_v1128; }
    { const char * tb_v1129 = "    tb_guard_thread(&here, TB_THREAD_STACK);\n"; *(const char * *)tb_grow(v_lines) = tb_v1129; }
    { const char * tb_v1130 = "    void *r = t.run(t.arg);\n"; *(const char * *)tb_grow(v_lines) = tb_v1130; }
    { const char * tb_v1131 = "    __atomic_sub_fetch(&tb_gthreads, 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v1131; }
    { const char * tb_v1132 = "    stack_t ss, old;\n"; *(const char * *)tb_grow(v_lines) = tb_v1132; }
    { const char * tb_v1133 = "    ss.ss_sp = 0; ss.ss_size = 0; ss.ss_flags = SS_DISABLE;\n"; *(const char * *)tb_grow(v_lines) = tb_v1133; }
    { const char * tb_v1134 = "    if (sigaltstack(&ss, &old) == 0 && old.ss_sp) free(old.ss_sp);\n"; *(const char * *)tb_grow(v_lines) = tb_v1134; }
    { const char * tb_v1135 = "    return r;\n"; *(const char * *)tb_grow(v_lines) = tb_v1135; }
    { const char * tb_v1136 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1136; }
    { const char * tb_v1137 = "// поток с 8 МБ стека (на Mac по умолчанию всего 512 КБ) и с понятным сообщением при переполнении\n"; *(const char * *)tb_grow(v_lines) = tb_v1137; }
    { const char * tb_v1138 = "static int tb_thread_create(pthread_t *th, void *(*run)(void *), void *arg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1138; }
    { const char * tb_v1139 = "    tb_tramp *t = malloc(sizeof(tb_tramp));\n"; *(const char * *)tb_grow(v_lines) = tb_v1139; }
    { const char * tb_v1140 = "    if (!t) return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v1140; }
    { const char * tb_v1141 = "    t->run = run; t->arg = arg;\n"; *(const char * *)tb_grow(v_lines) = tb_v1141; }
    { const char * tb_v1142 = "    pthread_attr_t at;\n"; *(const char * *)tb_grow(v_lines) = tb_v1142; }
