    { const char * tb_v1144 = "    pthread_attr_setstacksize(&at, (size_t)TB_THREAD_STACK);\n"; *(const char * *)tb_grow(v_lines) = tb_v1144; }
    { const char * tb_v1145 = "    __atomic_add_fetch(&tb_gthreads, 1, __ATOMIC_ACQ_REL);\n"; *(const char * *)tb_grow(v_lines) = tb_v1145; }
    { const char * tb_v1146 = "    int r = pthread_create(th, &at, tb_tramp_run, t);\n"; *(const char * *)tb_grow(v_lines) = tb_v1146; }
    { const char * tb_v1147 = "    pthread_attr_destroy(&at);\n"; *(const char * *)tb_grow(v_lines) = tb_v1147; }
    { const char * tb_v1148 = "    if (r != 0) { free(t); __atomic_sub_fetch(&tb_gthreads, 1, __ATOMIC_RELEASE); }\n"; *(const char * *)tb_grow(v_lines) = tb_v1148; }
    { const char * tb_v1149 = "    return r;\n"; *(const char * *)tb_grow(v_lines) = tb_v1149; }
    { const char * tb_v1150 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1150; }
    { const char * tb_v1151 = "#ifdef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v1151; }
    { const char * tb_v1152 = "static void tb_win_fatal(const char *m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1152; }
    { const char * tb_v1153 = "    DWORD w;\n"; *(const char * *)tb_grow(v_lines) = tb_v1153; }
