    { const char * tb_v1156 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1156; }
    { const char * tb_v1157 = "#define TB_WIN_STACK_MSG \"стек переполнен: функция зовёт себя слишком глубоко (рекурсия без конца?)\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v1157; }
    { const char * tb_v1158 = "// переполнение стека — сразу (это никогда не «нормальное» исключение)\n"; *(const char * *)tb_grow(v_lines) = tb_v1158; }
    { const char * tb_v1159 = "static LONG CALLBACK tb_win_overflow(EXCEPTION_POINTERS *e) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1159; }
    { const char * tb_v1160 = "    if (e->ExceptionRecord->ExceptionCode == EXCEPTION_STACK_OVERFLOW) tb_win_fatal(TB_WIN_STACK_MSG);\n"; *(const char * *)tb_grow(v_lines) = tb_v1160; }
    { const char * tb_v1161 = "    return EXCEPTION_CONTINUE_SEARCH;\n"; *(const char * *)tb_grow(v_lines) = tb_v1161; }
