    { const char * tb_v1168 = "        char *a = e->ExceptionRecord->NumberParameters >= 2 ? (char *)e->ExceptionRecord->ExceptionInformation[1] : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1168; }
