    { const char * tb_v1174 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1174; }
    { const char * tb_v1175 = "// начало программы на Windows: русский текст в консоли, цвета, слова запуска в UTF-8,\n"; *(const char * *)tb_grow(v_lines) = tb_v1175; }
    { const char * tb_v1176 = "// понятное сообщение при переполнении стека\n"; *(const char * *)tb_grow(v_lines) = tb_v1176; }
    { const char * tb_v1177 = "static void tb_win_init(int *argc, char ***argv) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1177; }
    { const char * tb_v1178 = "    SetConsoleOutputCP(CP_UTF8);\n"; *(const char * *)tb_grow(v_lines) = tb_v1178; }
    { const char * tb_v1179 = "    SetConsoleCP(CP_UTF8);\n"; *(const char * *)tb_grow(v_lines) = tb_v1179; }
    { const char * tb_v1180 = "    // \\n остаётся \\n (как на Linux и Mac): одинаковый вывод в файл и в трубу\n"; *(const char * *)tb_grow(v_lines) = tb_v1180; }
    { const char * tb_v1181 = "    _setmode(_fileno(stdout), _O_BINARY);\n"; *(const char * *)tb_grow(v_lines) = tb_v1181; }
    { const char * tb_v1182 = "    _setmode(_fileno(stderr), _O_BINARY);\n"; *(const char * *)tb_grow(v_lines) = tb_v1182; }
