    { const char * tb_v1186 = "    if (GetConsoleMode(err, &mode) && SetConsoleMode(err, mode | 0x0004)) tb_win_vt = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v1186; }
    { const char * tb_v1187 = "    int n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1187; }
    { const char * tb_v1188 = "    wchar_t **wa = CommandLineToArgvW(GetCommandLineW(), &n);\n"; *(const char * *)tb_grow(v_lines) = tb_v1188; }
