    { const char * tb_v1197 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v1197; }
    { const char * tb_v1198 = "    AddVectoredExceptionHandler(1, tb_win_overflow);\n"; *(const char * *)tb_grow(v_lines) = tb_v1198; }
    { const char * tb_v1199 = "    SetUnhandledExceptionFilter(tb_win_crashed);\n"; *(const char * *)tb_grow(v_lines) = tb_v1199; }
    { const char * tb_v1200 = "    SetErrorMode(SEM_FAILCRITICALERRORS | SEM_NOGPFAULTERRORBOX);\n"; *(const char * *)tb_grow(v_lines) = tb_v1200; }
    { const char * tb_v1201 = "    ULONG g = 65536;\n"; *(const char * *)tb_grow(v_lines) = tb_v1201; }
    { const char * tb_v1202 = "    SetThreadStackGuarantee(&g);\n"; *(const char * *)tb_grow(v_lines) = tb_v1202; }
