    { const char * tb_v1219 = "    sigaction(SIGBUS, &sa, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v1219; }
    { const char * tb_v1220 = "    char here;\n"; *(const char * *)tb_grow(v_lines) = tb_v1220; }
    { const char * tb_v1221 = "    tb_main_sp = &here;\n"; *(const char * *)tb_grow(v_lines) = tb_v1221; }
    { const char * tb_v1222 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1222; }
    { const char * tb_v1223 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v1223; }
    { const char * tb_v1224 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v1224; }
    { const char * tb_v1225 = "// ---------- temp: временная память ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v1225; }
    { const char * tb_v1226 = "// Внутри блока temp память берётся из больших кусков подряд (быстро, без malloc),\n"; *(const char * *)tb_grow(v_lines) = tb_v1226; }
    { const char * tb_v1227 = "// а в конце блока все куски отдаются разом. У каждого ядра свои куски.\n"; *(const char * *)tb_grow(v_lines) = tb_v1227; }
    { const char * tb_v1228 = "typedef struct { char *mem; long long size, used; } tb_chunk;\n"; *(const char * *)tb_grow(v_lines) = tb_v1228; }
    { const char * tb_v1229 = "typedef struct { int n; long long used; } tb_mark;\n"; *(const char * *)tb_grow(v_lines) = tb_v1229; }
    { const char * tb_v1230 = "static _Thread_local tb_chunk *tb_chunks = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1230; }
    { const char * tb_v1231 = "static _Thread_local int tb_nchunks = 0, tb_capchunks = 0, tb_temp_depth = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1231; }
    { const char * tb_v1232 = "static int tb_in_temp(const void *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1232; }
    { const char * tb_v1233 = "    for (int i = tb_nchunks - 1; i >= 0; i--) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1233; }
    { const char * tb_v1234 = "        if ((const char *)p >= tb_chunks[i].mem && (const char *)p < tb_chunks[i].mem + tb_chunks[i].size) return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v1234; }
    { const char * tb_v1235 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v1235; }
    { const char * tb_v1236 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1236; }
    { const char * tb_v1237 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1237; }
    { const char * tb_v1238 = "static void *tb_temp_alloc(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1238; }
    { const char * tb_v1239 = "    n = n > 0 ? (n + 15) & ~15LL : 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v1239; }
    { const char * tb_v1240 = "    tb_chunk *c = tb_nchunks > 0 ? &tb_chunks[tb_nchunks - 1] : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1240; }
    { const char * tb_v1241 = "    if (c == 0 || c->used + n > c->size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1241; }
    { const char * tb_v1242 = "        long long size = c != 0 ? c->size * 2 : (1LL << 20);\n"; *(const char * *)tb_grow(v_lines) = tb_v1242; }
    { const char * tb_v1243 = "        if (size < n) size = n;\n"; *(const char * *)tb_grow(v_lines) = tb_v1243; }
