    { const char * tb_v1407 = "extern void *mremap(void *old, size_t old_size, size_t new_size, int flags, ...);\n"; *(const char * *)tb_grow(v_lines) = tb_v1407; }
    { const char * tb_v1408 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v1408; }
