    { const char * tb_v2244 = "// ---------- http_get: страница из интернета через curl (есть на Mac и почти на любом Linux) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2244; }
    { const char * tb_v2245 = "static const char *tb_http_get(const char *url) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2245; }
