    { const char * tb_v2288 = "static const char *tb_js_ws(const char *p) { while (*p == ' ' || *p == '\\n' || *p == '\\r' || *p == '\\t') p++; return p; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2288; }
    { const char * tb_v2289 = "// пропустить одно значение; адрес после него или 0, если JSON сломан\n"; *(const char * *)tb_grow(v_lines) = tb_v2289; }
    { const char * tb_v2290 = "static const char *tb_js_skip(const char *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2290; }
    { const char * tb_v2291 = "    p = tb_js_ws(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v2291; }
    { const char * tb_v2292 = "    if (*p == '\"') {\n"; *(const char * *)tb_grow(v_lines) = tb_v2292; }
