    { const char * tb_v2295 = "        return *p ? p + 1 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2295; }
    { const char * tb_v2296 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2296; }
    { const char * tb_v2297 = "    if (*p == '{' || *p == '[') {\n"; *(const char * *)tb_grow(v_lines) = tb_v2297; }
    { const char * tb_v2298 = "        int d = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2298; }
    { const char * tb_v2299 = "        while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2299; }
    { const char * tb_v2300 = "            if (*p == '\"') { p = tb_js_skip(p); if (!p) return 0; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2300; }
    { const char * tb_v2301 = "            if (*p == '{' || *p == '[') d++;\n"; *(const char * *)tb_grow(v_lines) = tb_v2301; }
    { const char * tb_v2302 = "            else if (*p == '}' || *p == ']') { d--; if (d == 0) return p + 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2302; }
    { const char * tb_v2303 = "            p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v2303; }
