    { const char * tb_v2307 = "    const char *s = p;\n"; *(const char * *)tb_grow(v_lines) = tb_v2307; }
    { const char * tb_v2308 = "    while (*p && *p != ',' && *p != '}' && *p != ']' && *p != ' ' && *p != '\\n' && *p != '\\r' && *p != '\\t') p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v2308; }
    { const char * tb_v2309 = "    return p == s ? 0 : p;\n"; *(const char * *)tb_grow(v_lines) = tb_v2309; }
    { const char * tb_v2310 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2310; }
    { const char * tb_v2311 = "static int tb_js_hex(const char *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2311; }
    { const char * tb_v2312 = "    int v = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2312; }
    { const char * tb_v2313 = "    for (int i = 0; i < 4; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2313; }
    { const char * tb_v2314 = "        char ch = p[i]; v <<= 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v2314; }
    { const char * tb_v2315 = "        if (ch >= '0' && ch <= '9') v |= ch - '0';\n"; *(const char * *)tb_grow(v_lines) = tb_v2315; }
