    { const char * tb_v2320 = "    return v;\n"; *(const char * *)tb_grow(v_lines) = tb_v2320; }
    { const char * tb_v2321 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2321; }
    { const char * tb_v2322 = "// строка JSON (p смотрит на \") → обычный текст\n"; *(const char * *)tb_grow(v_lines) = tb_v2322; }
    { const char * tb_v2323 = "static const char *tb_js_str(const char *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2323; }
    { const char * tb_v2324 = "    const char *e = tb_js_skip(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v2324; }
    { const char * tb_v2325 = "    if (!e) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2325; }
    { const char * tb_v2326 = "    char *out = tb_tmem(e - p + 1), *o = out;\n"; *(const char * *)tb_grow(v_lines) = tb_v2326; }
    { const char * tb_v2327 = "    p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v2327; }
    { const char * tb_v2328 = "    while (*p != '\"') {\n"; *(const char * *)tb_grow(v_lines) = tb_v2328; }
    { const char * tb_v2329 = "        if (*p != '\\\\') { *o++ = *p++; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2329; }
    { const char * tb_v2330 = "        p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v2330; }
