    { const char * tb_v2338 = "            if (cp >= 0xD800 && cp < 0xDC00 && p[0] == '\\\\' && p[1] == 'u') {\n"; *(const char * *)tb_grow(v_lines) = tb_v2338; }
    { const char * tb_v2339 = "                int lo = tb_js_hex(p + 2);\n"; *(const char * *)tb_grow(v_lines) = tb_v2339; }
