    { const char * tb_v2657 = "        return ~0ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v2657; }
    { const char * tb_v2658 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2658; }
