    { const char * tb_v2695 = "static void *tb_obj_mem_np(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2695; }
    { const char * tb_v2696 = "    if (tb_temp_depth > 0) return tb_mem(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v2696; }
    { const char * tb_v2697 = "    return tb_gc_alloc_np(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v2697; }
    { const char * tb_v2698 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2698; }
    { const char * tb_v2699 = "// ---------- background: работа в своём потоке ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2699; }
    { const char * tb_v2700 = "#ifndef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v2700; }
    { const char * tb_v2701 = "typedef struct { pthread_t th; int done; void *res; } tb_task;\n"; *(const char * *)tb_grow(v_lines) = tb_v2701; }
    { const char * tb_v2702 = "static void tb_task_start(tb_task *t, void *(*run)(void *), void *arg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2702; }
    { const char * tb_v2703 = "    t->done = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2703; }
    { const char * tb_v2704 = "    if (tb_thread_create(&t->th, run, arg) != 0) tb_crash(0, \"не получилось запустить background\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2704; }
    { const char * tb_v2705 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2705; }
    { const char * tb_v2706 = "// a.wait: дождаться потока (один раз) и отдать адрес ответа\n"; *(const char * *)tb_grow(v_lines) = tb_v2706; }
    { const char * tb_v2707 = "static void *tb_wait(tb_task *t) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2707; }
    { const char * tb_v2708 = "    if (!t->done) { pthread_join(t->th, 0); t->done = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2708; }
    { const char * tb_v2709 = "    return t->res;\n"; *(const char * *)tb_grow(v_lines) = tb_v2709; }
    { const char * tb_v2710 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2710; }
    { const char * tb_v2711 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v2711; }
    { const char * tb_v2712 = "static int tb_dhas(tb_dict *d, const void *k) { return tb_dfind(d, k) >= 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2712; }
    { const char * tb_v2713 = "static void tb_dremove(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2713; }
    { const char * tb_v2714 = "    long long at = tb_dfind(d, k);\n"; *(const char * *)tb_grow(v_lines) = tb_v2714; }
    { const char * tb_v2715 = "    if (at < 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v2715; }
    { const char * tb_v2716 = "    if (d->mode != 0) tb_dto_hash(d);\n"; *(const char * *)tb_grow(v_lines) = tb_v2716; }
    { const char * tb_v2717 = "    long long last = d->keys->len - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2717; }
    { const char * tb_v2718 = "    // на место удалённого ставим последний: порядок меняется только у него\n"; *(const char * *)tb_grow(v_lines) = tb_v2718; }
    { const char * tb_v2719 = "    memcpy(d->keys->data + at * d->keys->size, d->keys->data + last * d->keys->size, d->keys->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v2719; }
    { const char * tb_v2720 = "    memcpy(d->vals->data + at * d->vals->size, d->vals->data + last * d->vals->size, d->vals->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v2720; }
    { const char * tb_v2721 = "    d->keys->len -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2721; }
