    { const char * tb_v2724 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2724; }
    { const char * tb_v2725 = "static tb_dict *tb_dict_from(int text, long long vsize, long long n, const void *keys, const void *vals) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2725; }
    { const char * tb_v2726 = "    tb_dict *d = tb_dict_new(text, vsize);\n"; *(const char * *)tb_grow(v_lines) = tb_v2726; }
    { const char * tb_v2727 = "    long long ksize = d->keys->size;\n"; *(const char * *)tb_grow(v_lines) = tb_v2727; }
    { const char * tb_v2728 = "    for (long long i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2728; }
    { const char * tb_v2729 = "        memcpy(tb_dput(d, (const char *)keys + i * ksize, 0), (const char *)vals + i * vsize, vsize);\n"; *(const char * *)tb_grow(v_lines) = tb_v2729; }
    { const char * tb_v2730 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2730; }
    { const char * tb_v2731 = "    return d;\n"; *(const char * *)tb_grow(v_lines) = tb_v2731; }
    { const char * tb_v2732 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2732; }
    { const char * tb_v2733 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2733; }
    { const char * tb_v2734 = "// ---------- on all cores: цикл на всех ядрах ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2734; }
    { const char * tb_v2735 = "// Работа делится на куски; каждое ядро берёт следующий свободный кусок,\n"; *(const char * *)tb_grow(v_lines) = tb_v2735; }
    { const char * tb_v2736 = "// пока они не кончатся (так ядра не простаивают, если куски разные по тяжести).\n"; *(const char * *)tb_grow(v_lines) = tb_v2736; }
    { const char * tb_v2737 = "// shared: каждое ядро копит своё на «листке», потом один раз добавляет под замком.\n"; *(const char * *)tb_grow(v_lines) = tb_v2737; }
    { const char * tb_v2738 = "static pthread_mutex_t tb_par_lock = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v2738; }
    { const char * tb_v2739 = "static int tb_cores(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2739; }
    { const char * tb_v2740 = "    const char *want = getenv(\"TB_CORES\");   // TB_CORES=1 — проверить на одном ядре\n"; *(const char * *)tb_grow(v_lines) = tb_v2740; }
    { const char * tb_v2741 = "    long n = want != 0 ? atol(want) : sysconf(_SC_NPROCESSORS_ONLN);\n"; *(const char * *)tb_grow(v_lines) = tb_v2741; }
    { const char * tb_v2742 = "    return n < 1 ? 1 : (n > 256 ? 256 : (int)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v2742; }
    { const char * tb_v2743 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2743; }
    { const char * tb_v2744 = "static void tb_par_run(void *(*work)(void *), void *job, long long total) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2744; }
    { const char * tb_v2745 = "    int n = tb_cores();\n"; *(const char * *)tb_grow(v_lines) = tb_v2745; }
    { const char * tb_v2746 = "    if (n > total) n = (int)total;\n"; *(const char * *)tb_grow(v_lines) = tb_v2746; }
    { const char * tb_v2747 = "    if (n < 1) n = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2747; }
    { const char * tb_v2748 = "    pthread_t t[256];\n"; *(const char * *)tb_grow(v_lines) = tb_v2748; }
    { const char * tb_v2749 = "    for (int i = 1; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2749; }
    { const char * tb_v2750 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v2750; }
    { const char * tb_v2751 = "        if (pthread_create(&t[i], 0, work, job) != 0) tb_crash(0, \"не получилось запустить ядро\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2751; }
    { const char * tb_v2752 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v2752; }
    { const char * tb_v2753 = "        if (tb_thread_create(&t[i], work, job) != 0) tb_crash(0, \"не получилось запустить ядро\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2753; }
    { const char * tb_v2754 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v2754; }
    { const char * tb_v2755 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2755; }
    { const char * tb_v2756 = "    work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v2756; }
    { const char * tb_v2757 = "    for (int i = 1; i < n; i++) pthread_join(t[i], 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v2757; }
    { const char * tb_v2758 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2758; }
    { const char * tb_v2759 = "static long long tb_par_step(long long total) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2759; }
    { const char * tb_v2760 = "    long long s = total / ((long long)tb_cores() * 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v2760; }
    { const char * tb_v2761 = "    return s < 1 ? 1 : s;\n"; *(const char * *)tb_grow(v_lines) = tb_v2761; }
    { const char * tb_v2762 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2762; }
    { const char * tb_v2763 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2763; }
    { const char * tb_v2764 = "// ---------- биты, адреса, порты, замки (danger и lock) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2764; }
    { const char * tb_v2765 = "static inline long long tb_band(long long a, long long b) { return a & b; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2765; }
