    { const char * tb_v2777 = "static inline void tb_wr16(long long a, long long v) { *(volatile uint16_t *)(uintptr_t)a = (uint16_t)v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2777; }
    { const char * tb_v2778 = "static inline void tb_wr32(long long a, long long v) { *(volatile uint32_t *)(uintptr_t)a = (uint32_t)v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2778; }
    { const char * tb_v2779 = "static inline void tb_wr64(long long a, long long v) { *(volatile uint64_t *)(uintptr_t)a = (uint64_t)v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2779; }
    { const char * tb_v2780 = "static inline long long tb_addr_of(tb_list *l) { return (long long)(uintptr_t)l->data; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2780; }
    { const char * tb_v2781 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v2781; }
